import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { 
    FaCalendarAlt, FaCheck, FaTimes, FaPlus, FaSync, 
    FaSave, FaFileAlt, FaClock, FaComment, 
    FaEye, FaBullseye, FaUsers, FaChevronRight,
    FaSpinner, FaStar, FaFire, FaRocket
} from 'react-icons/fa';
import { motion, AnimatePresence } from 'framer-motion';
import axios from 'axios';
import toast from 'react-hot-toast';

const DailyTracker = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [selectedDay, setSelectedDay] = useState(null);
    const [loading, setLoading] = useState(true);
    const [creating, setCreating] = useState(false);
    const [selectedTask, setSelectedTask] = useState(null);
    const [taskNote, setTaskNote] = useState('');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [showHistory, setShowHistory] = useState(false);
    const [hoveredDay, setHoveredDay] = useState(null);
    
    const today = new Date();
    const currentMonth = today.getMonth();
    const currentYear = today.getFullYear();
    const currentDay = today.getDate();
    
    const targetDate = new Date(2026, 10, 30);
    const daysRemaining = Math.max(0, Math.ceil((targetDate - today) / (1000 * 60 * 60 * 24)));
    
    const getDaysInMonth = (month, year) => {
        return new Date(year, month + 1, 0).getDate();
    };
    
    const daysInMonth = getDaysInMonth(currentMonth, currentYear);
    const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 
                        'July', 'August', 'September', 'October', 'November', 'December'];

    useEffect(() => {
        if (user) {
            fetchTasks();
        }
    }, [user]);

    const fetchTasks = async () => {
        try {
            const response = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(response.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch tasks:', error);
            toast.error('Failed to load tasks');
            setLoading(false);
        }
    };

    const createTaskForDay = async (day) => {
        setCreating(true);
        try {
            const date = new Date(currentYear, currentMonth, day);
            const dateStr = date.toISOString().split('T')[0];
            
            const response = await axios.post(
                `http://localhost:8081/api/tasks/user/${user.id}/day/${day}?date=${dateStr}`,
                {},
                { 
                    headers: { 
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    } 
                }
            );
            setTasks([...tasks, response.data]);
            toast.success(`Tasks created for ${monthNames[currentMonth]} ${day}`);
            return response.data;
        } catch (error) {
            console.error('Failed to create task:', error);
            toast.error('Failed to create tasks');
            return null;
        } finally {
            setCreating(false);
        }
    };

    const toggleTask = async (taskId, field) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { ...task, [field]: !task[field] };
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
            toast.success('✅ Task updated!');
        } catch (error) {
            console.error('Failed to update task:', error);
            toast.error('Failed to update task');
        }
    };

    const updateTaskNote = async (taskId, note) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { ...task, notes: note };
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
            toast.success('💾 Note saved!');
        } catch (error) {
            console.error('Failed to save note:', error);
            toast.error('Failed to save note');
        }
    };

    const handleDayClick = async (day) => {
        setSelectedDay(day);
        const dayTasks = tasks.filter(task => task.day === day);
        if (dayTasks.length === 0 && !creating) {
            await createTaskForDay(day);
        }
    };

    const handleTaskClick = (task, field) => {
        const labels = {
            javaCompleted: 'Java',
            leetcodeCompleted: 'LeetCode',
            dsaCompleted: 'DSA/OOP',
            sqlCompleted: 'SQL/APIs',
            projectCompleted: 'Project',
            githubCompleted: 'GitHub/Portfolio'
        };
        setSelectedTask({ task, field, label: labels[field] });
        setTaskNote(task.notes || '');
        setIsModalOpen(true);
    };

    const saveNote = () => {
        if (selectedTask) {
            updateTaskNote(selectedTask.task.id, taskNote);
            setIsModalOpen(false);
        }
    };

    const getDayTasks = (day) => tasks.filter(task => task.day === day);

    const getDayStatus = (day) => {
        const dayTasks = getDayTasks(day);
        if (dayTasks.length === 0) return 'empty';
        const completed = dayTasks.filter(t => t.overallCompleted).length;
        if (completed === dayTasks.length) return 'done';
        if (completed > 0) return 'partial';
        return 'started';
    };

    const tasksWithNotes = tasks.filter(t => t.notes && t.notes.trim() !== '');
    const totalCompleted = tasks.filter(t => t.overallCompleted).length;
    const totalTasks = tasks.length;
    const progressPercent = totalTasks > 0 ? Math.round((totalCompleted / totalTasks) * 100) : 0;

    const getStatusColor = (status) => {
        switch(status) {
            case 'done': return 'bg-emerald-500';
            case 'partial': return 'bg-amber-400';
            case 'started': return 'bg-blue-400';
            default: return 'bg-gray-100';
        }
    };

    const getStatusText = (status) => {
        switch(status) {
            case 'done': return '✅ Done';
            case 'partial': return '🟡 Partial';
            case 'started': return '🔵 Started';
            default: return '⬜ Empty';
        }
    };

    if (loading) {
        return (
            <div className="d-flex justify-content-center align-items-center" style={{ height: '60vh' }}>
                <div className="text-center">
                    <div className="spinner-border text-primary" role="status" style={{ width: '3rem', height: '3rem' }}>
                        <span className="visually-hidden">Loading...</span>
                    </div>
                    <p className="text-muted mt-3">Loading your tasks...</p>
                </div>
            </div>
        );
    }

    const taskLabels = [
        { key: 'javaCompleted', label: '☕ Java (1.5h)', icon: '📚' },
        { key: 'leetcodeCompleted', label: '💻 LeetCode (1+)', icon: '🎯' },
        { key: 'dsaCompleted', label: '📊 DSA/OOP (1h)', icon: '🧩' },
        { key: 'sqlCompleted', label: '🗄️ SQL/APIs (1h)', icon: '🔗' },
        { key: 'projectCompleted', label: '🚀 Project (2-3h)', icon: '⚡' },
        { key: 'githubCompleted', label: '📁 GitHub/Portfolio', icon: '📝' }
    ];

    const calendarDays = [];
    for (let day = 1; day <= daysInMonth; day++) {
        calendarDays.push(day);
    }

    const weekDays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    return (
        <div className="container-fluid p-0">
            {/* Modal */}
            <AnimatePresence>
                {isModalOpen && selectedTask && (
                    <motion.div 
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="modal show d-block" 
                        style={{ backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 1050 }}
                        tabIndex="-1"
                    >
                        <div className="modal-dialog modal-dialog-centered modal-md">
                            <motion.div 
                                initial={{ scale: 0.9, y: 20 }}
                                animate={{ scale: 1, y: 0 }}
                                exit={{ scale: 0.9, y: 20 }}
                                className="modal-content rounded-4 border-0 shadow-lg"
                            >
                                <div className="modal-header border-0 pb-0">
                                    <div>
                                        <h5 className="modal-title fw-bold">
                                            <span className="text-primary">{selectedTask.label}</span>
                                            <span className="text-muted fs-6 fw-normal ms-2">
                                                - {monthNames[currentMonth]} {selectedTask.task.day}
                                            </span>
                                        </h5>
                                        <p className="text-muted small mb-0">📝 Add your learning notes</p>
                                    </div>
                                    <button 
                                        onClick={() => setIsModalOpen(false)}
                                        className="btn-close"
                                    />
                                </div>
                                <div className="modal-body pt-3">
                                    <div className="mb-3">
                                        <label className="form-label fw-semibold small">
                                            <FaComment className="me-1 text-primary" /> What did you learn today?
                                        </label>
                                        <textarea
                                            value={taskNote}
                                            onChange={(e) => setTaskNote(e.target.value)}
                                            className="form-control rounded-3"
                                            rows="5"
                                            placeholder="📝 Write what you studied, concepts learned, problems solved..."
                                            style={{ resize: 'none' }}
                                        />
                                    </div>
                                </div>
                                <div className="modal-footer border-0 pt-0">
                                    <button
                                        onClick={() => setIsModalOpen(false)}
                                        className="btn btn-light rounded-pill px-4"
                                    >
                                        Cancel
                                    </button>
                                    <button
                                        onClick={saveNote}
                                        className="btn btn-primary rounded-pill px-4"
                                    >
                                        <FaSave className="me-2" /> Save Note
                                    </button>
                                </div>
                            </motion.div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Header */}
            <motion.div 
                initial={{ opacity: 0, y: -20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white rounded-4 shadow-sm p-4 mb-4"
            >
                <div className="d-flex flex-wrap justify-content-between align-items-center">
                    <div className="d-flex align-items-center gap-3">
                        <div className="bg-primary bg-opacity-10 p-3 rounded-4">
                            <FaCalendarAlt size={28} className="text-primary" />
                        </div>
                        <div>
                            <h4 className="fw-bold mb-0">
                                📅 {monthNames[currentMonth]} {currentYear}
                            </h4>
                            <div className="d-flex gap-3 text-muted small">
                                <span>Today: <strong className="text-dark">{currentDay} {monthNames[currentMonth]}</strong></span>
                                <span className="text-muted">•</span>
                                <span className="text-warning fw-semibold">
                                    <FaBullseye className="me-1" /> {daysRemaining} days until target
                                </span>
                            </div>
                        </div>
                    </div>
                    <div className="d-flex gap-2 mt-2 mt-sm-0">
                        <div className="bg-light rounded-pill px-3 py-2 d-flex align-items-center gap-2">
                            <FaUsers className="text-primary" />
                            <span className="fw-semibold">{tasksWithNotes.length}</span>
                            <span className="text-muted small">notes</span>
                        </div>
                        <div className="bg-success bg-opacity-10 rounded-pill px-3 py-2 d-flex align-items-center gap-2">
                            <FaCheck className="text-success" />
                            <span className="fw-semibold">{progressPercent}%</span>
                            <span className="text-muted small">done</span>
                        </div>
                        <button 
                            onClick={fetchTasks}
                            className="btn btn-outline-secondary rounded-pill px-3"
                        >
                            <FaSync className="me-1" /> Refresh
                        </button>
                    </div>
                </div>
            </motion.div>

            {/* Progress Bar */}
            <motion.div 
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                className="mb-4"
            >
                <div className="d-flex justify-content-between align-items-center mb-1">
                    <span className="text-muted small fw-semibold">Overall Progress</span>
                    <span className="fw-bold text-primary">{progressPercent}%</span>
                </div>
                <div className="progress" style={{ height: '8px', background: '#e9ecef', borderRadius: '10px' }}>
                    <motion.div 
                        initial={{ width: 0 }}
                        animate={{ width: `${progressPercent}%` }}
                        transition={{ duration: 0.8, ease: "easeOut" }}
                        className="progress-bar bg-gradient-to-r from-primary to-purple-600"
                        style={{ borderRadius: '10px' }}
                    />
                </div>
            </motion.div>

            <div className="row g-4">
                {/* Calendar */}
                <div className="col-lg-8">
                    <motion.div 
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        className="bg-white rounded-4 shadow-sm p-4"
                    >
                        <div className="d-flex justify-content-between align-items-center mb-3">
                            <h6 className="fw-bold mb-0">📆 Calendar</h6>
                            <div className="d-flex gap-2">
                                <span className="badge bg-emerald-500 text-white rounded-pill">Done</span>
                                <span className="badge bg-amber-400 text-white rounded-pill">Partial</span>
                                <span className="badge bg-blue-400 text-white rounded-pill">Started</span>
                                <span className="badge bg-gray-200 text-dark rounded-pill">Empty</span>
                            </div>
                        </div>
                        <div className="row g-1">
                            {weekDays.map(day => (
                                <div key={day} className="col text-center text-muted small fw-semibold py-1">
                                    {day}
                                </div>
                            ))}
                            {calendarDays.map((day) => {
                                const status = getDayStatus(day);
                                const bgColor = getStatusColor(status);
                                const isSelected = selectedDay === day;
                                const isToday = day === currentDay && currentMonth === new Date().getMonth();
                                const isHovered = hoveredDay === day;
                                
                                return (
                                    <motion.div 
                                        key={day} 
                                        className="col p-1"
                                        whileHover={{ scale: 1.05 }}
                                        transition={{ type: "spring", stiffness: 300 }}
                                    >
                                        <button
                                            onClick={() => handleDayClick(day)}
                                            onMouseEnter={() => setHoveredDay(day)}
                                            onMouseLeave={() => setHoveredDay(null)}
                                            className={`w-100 btn ${bgColor} text-white rounded-3 fw-semibold position-relative transition-all`}
                                            style={{ 
                                                aspectRatio: '1/1',
                                                fontSize: '14px',
                                                padding: '4px',
                                                border: isSelected ? '3px solid #6366f1' : 'none',
                                                boxShadow: isSelected ? '0 0 0 3px rgba(99,102,241,0.3)' : 'none',
                                                transition: 'all 0.2s ease'
                                            }}
                                        >
                                            {day}
                                            {isToday && (
                                                <span className="position-absolute top-0 start-100 translate-middle p-1 bg-danger rounded-circle" style={{ width: '8px', height: '8px' }} />
                                            )}
                                        </button>
                                    </motion.div>
                                );
                            })}
                        </div>
                    </motion.div>
                </div>

                {/* Task List */}
                <div className="col-lg-4">
                    <motion.div 
                        initial={{ opacity: 0, x: 20 }}
                        animate={{ opacity: 1, x: 0 }}
                        className="bg-white rounded-4 shadow-sm p-4"
                        style={{ minHeight: '400px' }}
                    >
                        <div className="d-flex justify-content-between align-items-center mb-3">
                            <h6 className="fw-bold mb-0">
                                <FaFileAlt className="me-2 text-primary" />
                                {selectedDay ? `📋 Day ${selectedDay}` : 'Select a day'}
                            </h6>
                            {selectedDay && (
                                <button
                                    onClick={() => {
                                        const dayTasks = tasks.filter(t => t.day === selectedDay);
                                        if (dayTasks.length > 0 && dayTasks[0].notes) {
                                            setTaskNote(dayTasks[0].notes);
                                            setIsModalOpen(true);
                                        }
                                    }}
                                    className="btn btn-sm btn-link text-primary p-0"
                                >
                                    <FaComment size={16} />
                                </button>
                            )}
                        </div>
                        
                        {selectedDay ? (
                            <div className="d-flex flex-column gap-2">
                                {taskLabels.map(({ key, label, icon }) => {
                                    const dayTasks = getDayTasks(selectedDay);
                                    const task = dayTasks[0];
                                    const isCompleted = task ? task[key] : false;
                                    const hasNote = task?.notes && task.notes.trim() !== '';
                                    
                                    return (
                                        <motion.div
                                            key={key}
                                            whileHover={{ scale: 1.02, x: 4 }}
                                            transition={{ type: "spring", stiffness: 400 }}
                                            onClick={() => task && handleTaskClick(task, key)}
                                            className={`d-flex justify-content-between align-items-center p-2 rounded-3 cursor-pointer transition-all ${
                                                isCompleted ? 'bg-emerald-50 border-l-4 border-emerald-500' : 'bg-gray-50 border-l-4 border-gray-300'
                                            }`}
                                            style={{ cursor: 'pointer' }}
                                        >
                                            <div className="d-flex align-items-center gap-2">
                                                <span style={{ fontSize: '18px' }}>{icon}</span>
                                                <span className={`small ${isCompleted ? 'text-muted text-decoration-line-through' : ''}`}>
                                                    {label}
                                                </span>
                                                {hasNote && (
                                                    <span className="badge bg-info text-white rounded-pill" style={{ fontSize: '8px' }}>
                                                        <FaComment size={10} /> note
                                                    </span>
                                                )}
                                            </div>
                                            <button
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (task) toggleTask(task.id, key);
                                                }}
                                                className={`btn btn-sm rounded-circle p-1 ${
                                                    isCompleted ? 'btn-success' : 'btn-outline-secondary'
                                                }`}
                                                style={{ width: '28px', height: '28px' }}
                                            >
                                                {isCompleted ? <FaCheck size={12} /> : <FaTimes size={12} />}
                                            </button>
                                        </motion.div>
                                    );
                                })}
                                
                                {getDayTasks(selectedDay).length === 0 && !creating && (
                                    <motion.div 
                                        initial={{ opacity: 0 }}
                                        animate={{ opacity: 1 }}
                                        className="text-center py-5"
                                    >
                                        <div className="bg-primary bg-opacity-10 rounded-circle d-flex align-items-center justify-content-center mx-auto mb-3" style={{ width: '64px', height: '64px' }}>
                                            <FaPlus size={24} className="text-primary" />
                                        </div>
                                        <p className="text-muted small mb-3">No tasks for this day</p>
                                        <button
                                            onClick={() => handleDayClick(selectedDay)}
                                            className="btn btn-primary rounded-pill px-4"
                                        >
                                            <FaPlus className="me-2" /> Create Tasks
                                        </button>
                                    </motion.div>
                                )}
                                
                                {creating && (
                                    <div className="text-center py-5">
                                        <FaSpinner className="fa-spin text-primary" size={32} />
                                        <p className="text-muted small mt-2">Creating tasks...</p>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="d-flex align-items-center justify-content-center py-5 text-muted">
                                <div className="text-center">
                                    <FaCalendarAlt size={48} className="text-gray-300 mb-3" />
                                    <p className="small">👆 Click a day on the calendar to start</p>
                                </div>
                            </div>
                        )}
                    </motion.div>
                </div>
            </div>

            {/* Footer */}
            <motion.div 
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="mt-4 bg-white rounded-4 shadow-sm p-3 d-flex flex-wrap justify-content-between align-items-center gap-2"
            >
                <div className="d-flex align-items-center gap-2 text-muted small">
                    <FaComment className="text-primary" />
                    <span>Click any task to add communication notes</span>
                </div>
                {tasksWithNotes.length > 0 && (
                    <button
                        onClick={() => setShowHistory(!showHistory)}
                        className="btn btn-sm btn-outline-primary rounded-pill px-3"
                    >
                        <FaEye className="me-1" />
                        {showHistory ? 'Hide all notes' : `View all notes (${tasksWithNotes.length})`}
                    </button>
                )}
            </motion.div>

            {/* Notes History */}
            <AnimatePresence>
                {showHistory && tasksWithNotes.length > 0 && (
                    <motion.div 
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        className="mt-3 bg-white rounded-4 shadow-sm p-4 overflow-hidden"
                    >
                        <h6 className="fw-bold mb-3">
                            <FaComment className="me-2 text-primary" />
                            Communication Notes ({tasksWithNotes.length})
                        </h6>
                        <div className="d-flex flex-column gap-2" style={{ maxHeight: '300px', overflowY: 'auto' }}>
                            {tasksWithNotes.map((task, index) => (
                                <motion.div 
                                    key={task.id}
                                    initial={{ opacity: 0, x: -20 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    transition={{ delay: index * 0.05 }}
                                    className="bg-gray-50 rounded-3 p-3"
                                >
                                    <div className="d-flex justify-content-between align-items-start">
                                        <div>
                                            <span className="fw-semibold small">
                                                📅 {monthNames[currentMonth]} {task.day}
                                            </span>
                                            <p className="text-muted small mb-0 mt-1">{task.notes}</p>
                                        </div>
                                        <span className="text-muted small">
                                            {task.updatedAt ? new Date(task.updatedAt).toLocaleDateString() : 'Today'}
                                        </span>
                                    </div>
                                </motion.div>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default DailyTracker;
